from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework.exceptions import PermissionDenied, NotFound
from cacheops import invalidate_obj
from .models import AnalyticsReport

class ReportCachePurgeView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, report_id: str):
        try:
            report = AnalyticsReport.objects.get(id=report_id)
        except AnalyticsReport.DoesNotExist:
            raise NotFound("Report not found")

        # Verify the report belongs to the requesting user's organization
        if report.organization != request.user.organization and not request.user.is_staff:
            raise PermissionDenied("You do not have permission to invalidate cache for this report")

        invalidate_obj(report)
        return Response({'status': 'invalidated', 'report_id': str(report.id)})
